// functions/src/discoverUrls.ts
//
// Discover results are generated by Gemini from Google Custom Search snippets,
// so any URL in them is untrusted. scholarshipSuggestions[].applyUrl is opened
// by the mobile app (Linking.openURL, which follows ANY scheme — upi://pay,
// tel:, sms:, app deep links) and rendered as a link on web. Only plain http(s)
// URLs are passed through; anything else is removed before the result is
// returned or cached. Applied to cached results too, since entries generated
// before this check may still hold an unsafe value.

const ALLOWED_PROTOCOLS = new Set(["http:", "https:"]);

/** The URL, normalised, if it is a well-formed http(s) URL with a host; otherwise null. */
export function safeHttpUrl(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const raw = value.trim();
  if (!raw) return null;
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    return null;
  }
  if (!ALLOWED_PROTOCOLS.has(url.protocol) || !url.hostname) return null;
  return url.toString();
}

/** Returns a copy of a Discover result whose scholarship applyUrl values are
 *  safe http(s) URLs or absent. Everything else is left untouched. */
export function sanitizeDiscoverResult<T extends Record<string, unknown>>(result: T): T {
  const list = result?.scholarshipSuggestions;
  if (!Array.isArray(list)) return result;
  const scholarshipSuggestions = list.map((s) => {
    if (!s || typeof s !== "object") return s;
    const { applyUrl, ...rest } = s as Record<string, unknown>;
    const safe = safeHttpUrl(applyUrl);
    return safe ? { ...rest, applyUrl: safe } : rest;
  });
  return { ...result, scholarshipSuggestions };
}
